actions.value:
@startuml
title Request intake with corrections
start
repeat
  :Receive request;
  :Validate details;
repeat while (Corrections needed?) is (yes) not (no)
partition "Request processing" {
  :Store request;
  fork
    :Send confirmation;
  fork again
    :Notify support team;
  end fork
}
:Show request status;
note right: The customer can track the request.
stop
@enduml

